        "exitFact": "Whether executed through physical enclosure, four-cornered logical negation, non-instrumental sitting, or the suspension of belief, subtraction operates on a single principle: what is fundamental does not need to be manufactured from scratch, because it becomes visible the moment superfluous noise is taken away."
