        "exitFact": "When Weil died at Grosvenor Sanatorium in Ashford, Kent in August 1943 after refusing to eat more than the official rations allotted to citizens in occupied France, her Marseilles notebooks remained unpublished in the hands of Gustave Thibon and Joe Bousquet."
