        "subtitle": "The War Against Thermal Drift and Noise",
        "slug": "introduction",
        "formalismMode": "introduction",
        "anchor": "Textbook histories of science are usually written as sequences of abstract ideas. In the standard telling, a theorist sits at a desk, writes down a new system of equations for gravity, electromagnetism, relativity, or quantum mechanics, and human understanding leaps forward.",
        "exitFact": "Distance is converted into the pitch of an endless screw or optical interference fringes; weak forces become the oscillation period of a torsion wire; and time locks to the microwave spin-flip of an isolated atom."
