        "slug": "the-hyperfine-pendulum",
        "formalismMode": "equation",
        "anchor": "Louis Essen and Jack V. L. Parry at the National Physical Laboratory (NPL) in Teddington, England in June 1955, constructing the five-foot copper-pipe 'Caesium I' atomic beam resonator and calibrating it over three years with U.S. Naval Observatory astronomer William Markowitz.",
        "exitFact": "In October 1967, the Thirteenth General Conference on Weights and Measures officially ended astronomy's multi-millennial stewardship of time, defining one international second as exactly 9,192,631,770 cycles of the Caesium-133 microwave transition measured at Teddington."
