        "title": "The Underground Dry-Cleaning Tank",
        "subtitle": "Raymond Davis Jr., the Homestake Mine, and the Missing Solar Neutrinos",
        "slug": "the-underground-dry-cleaning-tank",
        "formalismMode": "ledger_or_list",
