        "exitFact": "Although the Roman Inquisition placed Valla's treatise on the Index of Forbidden Books in 1559, Ulrich von Hutten printed it in Germany in 1517, where Martin Luther read it and realized the medieval papal claim to Western empire rested on a philological fabrication."
