        "exitFact": "Ten months after Ventris's broadcast, archaeologist Carl Blegen dug up a fresh Linear B tablet (Ta 641) at Pylos stamped with tiny pictograms of three-legged cauldrons and four-handled goblets; when decoded with Ventris's grid, the syllables spelled out the exact Greek words ti-ri-po-de ('tripods') and qe-to-ro-we ('four-eared')."
