        "exitFact": "After sixteen years at his optical machine collating nearly fifty thousand folio pages, Hinman proved that because Jaggard's pressmen corrected type on the fly without discarding earlier sheets, no two surviving copies of Shakespeare's First Folio have the exact same text."
