        "exitFact": "As the iron-fluorescence scan lines assembled on the Stanford monitor in August 2006, the forged gold icons vanished and revealed Archimedes calculating the volume of solids with actual infinite sets nineteen centuries before Isaac Newton and Gottfried Wilhelm Leibniz."
