        "exitFact": "In February 2024, without touching or unrolling a single millimeter of the two-thousand-year-old charcoal cylinder, the team extracted fifteen continuous columns of Greek text by the Epicurean philosopher Philodemus on music, food, and the mechanics of human pleasure."
