        "title": "The San Francisco Fault",
        "subtitle": "Earthquake Ruin and the Moral Equivalent of War",
        "slug": "the-san-francisco-fault",
        "formalismMode": "ledger_or_list",
        "anchor": "William James waking at 5:12 AM on April 18, 1906 as the San Andreas Fault ruptured across 296 miles (magnitude 7.9), shouting encouragement to the earthquake inside his shaking Stanford bedroom, boarding the last morning train into burning San Francisco for eight hours of field observation, publishing 'On Some Mental Effects of the Earthquake' in June 1906, and writing his final landmark essay 'The Moral Equivalent of War' (published February 1910 in International Conciliation, six months before his death from heart failure at Chocorua, New Hampshire on August 26, 1910).",
        "exitFact": "Twenty-three years after James died at his New Hampshire farmhouse in August 1910, his former Harvard student Franklin Delano Roosevelt put the 1910 proposal into federal statute by signing the Emergency Conservation Work Act of March 31, 1933, mobilizing three million young men into the Civilian Conservation Corps."
