        "anchor": "Ashish Vaswani, Noam Shazeer, Jakob Uszkoreit, and five colleagues at Google publishing 'Attention Is All You Need' in June 2017, replacing sequential recurrent networks with parallel multi-head self-attention.",
        "exitFact": "Because the path length between any two words in a Transformer is a single direct hop rather than a chain of sequential steps, a pronoun at the end of a ten-thousand-word contract can attend directly to the noun on page one."
