        "anchor": "Arthur Samuel's 1959 IBM 701 self-play checkers program, Gerald Tesauro's 1992 TD-Gammon, and DeepMind's AlphaGo playing Move 37 against eighteen-time world champion Lee Sedol in Seoul on March 10, 2016.",
        "exitFact": "When DeepMind's successor program AlphaZero was given only the bare rules of Go with zero human games to study, it defeated the version of AlphaGo that beat Lee Sedol by one hundred games to zero after seventy-two hours of self-play."
