        "label": "Introduction",
        "title": "Vaccines",
        "subtitle": "Teaching the Adaptive Immune System Before the Plague Arrives",
        "slug": "introduction",
        "formalismMode": "introduction",
        "anchor": "Every acute infectious disease is a kinetic race between two exponential processes operating on mismatched clocks. Once a pathogenic virus or bacterium breaches a mucosal surface or enters the bloodstream, it replicates on a timescale of minutes to hours.",
