        "exitFact": "Joseph Meister developed neutralizing antibodies before the virus reached his spinal cord and survived to serve as gatekeeper of the Pasteur Institute, establishing the post-exposure prophylaxis paradigm that today pairs cell-culture inactivated vaccine with wound-infiltrated rabies immunoglobulin."
