        "slug": "systemic-igg-versus-mucosal-iga",
        "formalismMode": "ledger_or_list",
        "anchor": "After Isabel Morgan typed the three poliovirus serotypes and John Enders, Thomas Weller, and Frederick Robbins cultured poliovirus in non-neural tissue in 1949, Jonas Salk inactivated all three serotypes with 1-to-4,000 formalin for Thomas Francis Jr.'s 1954 field trial across 1.8 million children. Weeks after the April 12, 1955 announcement, inadequate filtration of cellular aggregates at Cutter Laboratories shielded live Mahoney type 1 virus and paralyzed 200 recipients, before Albert Sabin's oral attenuated strains introduced intestinal secretory IgA immunity between 1959 and 1961.",
        "exitFact": "Combining Sabin's oral vaccine to block fecal-oral intestinal transmission with Salk's inactivated vaccine to prevent vaccine-associated paralytic reversion has reduced global poliomyelitis by more than 99.9 percent since 1988 and eradicated wild serotypes 2 and 3."
