        "exitFact": "Following Taiwan's July 1984 rollout of universal newborn hepatitis B immunization, chronic HBsAg carriage in children dropped from nearly 10 percent to below 0.6 percent and hepatocellular carcinoma incidence in vaccinated cohorts declined by 75 to 80 percent."
