        "title": "Herd Thresholds and the Trap of Antibody-Dependent Enhancement",
        "subtitle": "From Ronald Ross's Reproduction Number to Dengue Hemorrhagic Fever and the 1966 RSV Trial",
        "slug": "herd-thresholds-and-the-trap-of-antibody-dependent-enhancement",
        "formalismMode": "equation",
        "anchor": "While Ronald Ross and George Macdonald's basic reproduction number governs how neutralizing antibodies halt epidemics once population immunity crosses the critical threshold, two clinical catastrophes revealed how sub-neutralizing or misdirected antibodies amplify viral disease. In the 1960s and 1970s, Scott Halstead demonstrated that heterotypic dengue antibodies complex with virions to infect Fc-gamma-receptor-bearing monocytes, while the 1966 NIH clinical trial of formalin-inactivated Respiratory Syncytial Virus hospitalized 80 percent of RSV-infected vaccinees with two infant deaths.",
        "exitFact": "Subsequent immunological forensics proved that formalin denaturation had flipped the RSV fusion glycoprotein into its spent postfusion state, eliciting low-avidity antibodies that deposited immune complexes and triggered Th2-skewed pulmonary eosinophilia."
